import React from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, spring, Easing, Img } from "remotion";
import { COLORS, FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const GOLD_GRADIENT = 'linear-gradient(100deg, #F8E9B8 0%, #EBCD86 50%, #D2AB5E 100%)';

const WHITE = "rgba(255,255,255,1)";

// Font size that keeps `text` on one line within `avail` px (rough glyph-width estimate);
// anything still too long wraps instead of being clipped.
const fit = (text: string, base: number, avail: number, k: number): number =>
  Math.max(base * 0.45, Math.min(base, avail / (Math.max(1, text.length) * k)));

const AgenteRevelacaoDourada: React.FC<PrimitiveProps> = ({ anim, fps, format, frame }) => {
  const f = useCurrentFrame();
  const W = frame.width;
  const H = frame.height;
  const L = Math.max(1, Math.round((anim.end - anim.start) * fps));

  const p = (anim.params ?? {}) as Record<string, unknown>;
  const str = (k: string): string => (p[k] == null ? "" : String(p[k]).trim());
  const src = String(anim.params?.src ?? "");
  const name = str("name") || String(anim.text ?? "").trim();
  // The Licença AMI: a third gold pill under the phone and email ("11220" → "Licença AMI 11220").
  const amiRaw = str("ami");
  const ami = amiRaw ? (amiRaw.toLowerCase().includes("ami") ? amiRaw : `Licença AMI ${amiRaw}`) : "";
  const contacts = [str("phone"), str("email"), ami].filter(Boolean);

  const land = format === "landscape";
  const half = format === "half";
  const u = land ? H / 1080 : half ? (H / 960) * 0.85 : W / 1080;
  // The photo is the subject: it takes most of the frame, the text sizes around what is left.
  const imgW = land ? W * 0.64 : W;
  const imgH = land ? H : half ? H * 0.8 : H * 0.77;
  const textW = land ? W * 0.32 : W * 0.9;
  const gap = (land ? 48 : half ? 14 : 26) * u;

  // Timing: the photo opens first, then the name drops in, then the contacts rise.
  const dur = Math.max(1, Math.round(Math.min(0.7 * fps, 0.25 * L)));
  const imgIn = interpolate(f, [0, dur], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.16, 1, 0.3, 1),
  });
  const at = (delay: number): number =>
    spring({
      frame: f - Math.round(delay * dur),
      fps,
      durationInFrames: dur,
      config: { damping: 14, stiffness: 160 },
    });
  const sName = at(0.5);

  // Light-gold plates: the intro card's exact gold gradient (fixed, not the theme accent, so both match).
  const plateShadow = `0 ${4 * u}px ${16 * u}px rgba(0,0,0,0.3)`;

  const namePadX = (half ? 28 : 40) * u;
  const namePadY = (half ? 10 : 16) * u;
  const longestWord = name.split(/\s+/).reduce((a, w) => (w.length > a.length ? w : a), "");
  const nameSize = fit(longestWord, (land ? 96 : half ? 62 : 88) * u, textW - 2 * namePadX, 0.62);

  const btnPadX = 44 * u;
  const btnPadY = 20 * u;
  const btnMax = half ? (textW - 20 * u) / 2 : textW;
  const btnBase = (half ? 32 : 44) * u;

  const inset = `${(1 - imgIn) * 50}%`;

  const nameEl = name ? (
    <div
      style={{
        background: GOLD_GRADIENT,
        boxShadow: plateShadow,
        borderRadius: 14 * u,
        padding: `${namePadY}px ${namePadX}px`,
        maxWidth: textW,
        boxSizing: "border-box",
        opacity: sName,
        transform: `translateY(${(1 - sName) * -30 * u}px)`,
      }}
    >
      <div
        style={{
          fontFamily: FONTS.display,
          fontWeight: 800,
          fontStyle: "italic",
          textTransform: "uppercase",
          fontSize: nameSize,
          lineHeight: 1,
          color: WHITE,
          // White shade: a soft white halo, with a dark drop underneath so it reads on the light gold.
          textShadow: `0 0 ${20 * u}px rgba(255,255,255,0.85), 0 0 ${6 * u}px rgba(255,255,255,0.7), 0 ${3 * u}px ${8 * u}px rgba(0,0,0,0.55)`,
          textAlign: land ? "left" : "center",
          overflowWrap: "break-word",
        }}
      >
        {name}
      </div>
    </div>
  ) : null;

  // No border, outline or shadow around the photo: only the clip reveal.
  const imageEl = (
    <div
      style={{
        position: "relative",
        flexShrink: 0,
        width: imgW,
        height: imgH,
        backgroundColor: src ? undefined : COLORS.vellum,
        overflow: "hidden",
        border: "none",
        outline: "none",
        boxShadow: "none",
        clipPath: `inset(${inset} ${inset} ${inset} ${inset})`,
        transform: `scale(${0.9 + 0.1 * imgIn})`,
      }}
    >
      {src ? (
        <Img
          src={src}
          style={{
            display: "block",
            width: "100%",
            height: "100%",
            objectFit: "cover",
            border: "none",
            outline: "none",
            transform: `scale(${1.14 - 0.12 * imgIn})`,
          }}
        />
      ) : (
        <>
          <div
            style={{
              position: "absolute",
              left: "36%",
              top: "18%",
              width: "28%",
              aspectRatio: "1",
              borderRadius: "50%",
              backgroundColor: COLORS.mutedOnLight,
              opacity: 0.45,
            }}
          />
          <div
            style={{
              position: "absolute",
              left: "20%",
              bottom: 0,
              width: "60%",
              height: "34%",
              borderRadius: "50% 50% 0 0",
              backgroundColor: COLORS.mutedOnLight,
              opacity: 0.45,
            }}
          />
        </>
      )}
    </div>
  );

  const buttonsEl = contacts.length ? (
    <div
      style={{
        display: "flex",
        flexDirection: half ? "row" : "column",
        alignItems: land ? "flex-start" : "center",
        justifyContent: "center",
        gap: 20 * u,
        maxWidth: textW,
      }}
    >
      {contacts.map((c, i) => {
        const s = at(0.9 + i * 0.3);
        return (
          <div
            key={i}
            style={{
              background: GOLD_GRADIENT,
              boxShadow: plateShadow,
              color: COLORS.ink,
              borderRadius: 999,
              padding: `${btnPadY}px ${btnPadX}px`,
              maxWidth: btnMax,
              boxSizing: "border-box",
              fontFamily: FONTS.display,
              fontWeight: 800,
              fontStyle: "italic",
              fontSize: fit(c, btnBase, btnMax - 2 * btnPadX, 0.6),
              lineHeight: 1.1,
              textAlign: "center",
              overflowWrap: "anywhere",
              opacity: Math.min(1, s * 1.5),
              transform: `translateY(${(1 - s) * 40 * u}px) scale(${0.9 + 0.1 * s})`,
            }}
          >
            {c}
          </div>
        );
      })}
    </div>
  ) : null;

  return (
    <AbsoluteFill style={{ fontFamily: FONTS.display, alignItems: "center", justifyContent: "center" }}>
      <div style={{ display: "flex", flexDirection: land ? "row" : "column", alignItems: "center", gap }}>
        {!land && nameEl}
        {imageEl}
        {land ? (
          <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-start", gap: 36 * u, width: textW }}>
            {nameEl}
            {buttonsEl}
          </div>
        ) : (
          buttonsEl
        )}
      </div>
    </AbsoluteFill>
  );
};

export default AgenteRevelacaoDourada;

