import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, spring, Easing } from "remotion";
import { COLORS, FONTS, STYLE, headlineGradient, ENGRAVE_SHADOW, PANEL_SHADOW, textForBg } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

// Largest font (≤ base) that keeps `text` on one line inside `avail` px; `pad` = horizontal padding in em.
const fit = (text: string, base: number, avail: number, k: number, pad = 0): number =>
  Math.min(base, avail / (Math.max(1, text.length) * k + pad));

const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const AgenteRevelacao: React.FC<PrimitiveProps> = ({ anim, fps, dark, format, frame }) => {
  const f = useCurrentFrame();
  const W = frame.width;
  const H = frame.height;
  const L = Math.max(2, Math.round((anim.end - anim.start) * fps));

  const p = (anim.params ?? {}) as Record<string, unknown>;
  const src = String(anim.params?.src ?? "");
  const name = String(anim.text || p.name || "").trim();
  const rawContacts = p.contacts;
  const contacts = (Array.isArray(rawContacts) ? rawContacts : String(rawContacts ?? "").split(/\n|\|/))
    .map((c) => String(c ?? "").trim())
    .filter(Boolean)
    .slice(0, 4);

  const row = format === "half"; // photo left, name + contacts right
  const wide = format === "landscape"; // contacts sit side by side
  const s = Math.min(W, H) / 1080;
  const margin = 0.06 * Math.min(W, H);
  const side = row ? Math.min(0.52 * H, 0.44 * W) : wide ? 0.46 * H : 0.62 * W;
  const gap = (row ? 48 : 40) * s;
  const textW = row ? W - side - gap - 2 * margin : wide ? 0.7 * W : W - 2 * margin;

  const longestWord = name.split(/\s+/).reduce((a, w) => (w.length > a.length ? w : a), "");
  const nameSize = fit(longestWord, (row ? 76 : 96) * s, textW, 0.62);
  const pillBase = (row ? 34 : 44) * s;
  const pillAvail = wide ? textW / Math.max(1, Math.min(2, contacts.length)) - gap : textW;

  // Motion: slash wipe on the photo, then name drops in, then contacts pop up one by one.
  const at = (t: number, bouncy = false): number =>
    spring({
      frame: f - Math.round(t * L),
      fps,
      durationInFrames: Math.max(1, Math.round(0.14 * L)),
      config: bouncy ? { damping: 12, stiffness: 140, mass: 0.8 } : { damping: 200 },
    });
  const wipe = interpolate(f, [0, Math.max(1, Math.round(0.22 * L))], [0, 1], {
    ...clamp,
    easing: Easing.bezier(0.16, 1, 0.3, 1),
  });
  const sImg = at(0);
  const sName = at(0.12, true);
  const out = interpolate(f, [L - Math.max(1, Math.round(0.08 * L)), L], [1, 0], clamp);
  const edge = interpolate(wipe, [0, 1], [100, -20]); // slash top edge, rising to the right

  const textColor = dark ? COLORS.textOnDark : COLORS.textOnLight;
  const radius = STYLE.sharp ? 0 : 0.03 * side;

  const nameStyle: React.CSSProperties = {
    fontFamily: FONTS.display,
    fontWeight: FONTS.displayWeight,
    fontStyle: "italic",
    textTransform: "uppercase",
    fontSize: nameSize,
    lineHeight: 0.94,
    maxWidth: textW,
    overflowWrap: "break-word",
    padding: "0 0.08em",
    textAlign: row ? "left" : "center",
    opacity: Math.min(1, sName * 2),
    transform: `translateY(${(1 - sName) * -60 * s}px)`,
    ...(STYLE.headline === "gradient"
      ? { backgroundImage: headlineGradient(), WebkitBackgroundClip: "text", backgroundClip: "text", color: "transparent" }
      : { color: textColor, textShadow: ENGRAVE_SHADOW }),
  };

  const photo = (
    <div
      style={{
        width: side,
        height: side,
        flexShrink: 0,
        borderRadius: radius,
        border: `${Math.max(2, 6 * s)}px solid ${textColor}`,
        boxShadow: PANEL_SHADOW,
        boxSizing: "border-box",
        overflow: "hidden",
        position: "relative",
        clipPath: `polygon(0 ${edge + 20}%, 100% ${edge}%, 100% 100%, 0 100%)`,
        transform: `scale(${0.88 + 0.12 * sImg})`,
      }}
    >
      {src ? (
        <Img
          src={src}
          style={{ width: "100%", height: "100%", objectFit: "cover", transform: `scale(${1.15 - 0.15 * wipe})` }}
        />
      ) : (
        <AbsoluteFill style={{ backgroundColor: "rgba(0,0,0,.18)", alignItems: "center", justifyContent: "flex-end" }}>
          <div style={{ width: "34%", height: "34%", borderRadius: "50%", backgroundColor: "rgba(255,255,255,.22)", marginBottom: "4%" }} />
          <div style={{ width: "70%", height: "30%", borderRadius: "50% 50% 0 0", backgroundColor: "rgba(255,255,255,.22)" }} />
        </AbsoluteFill>
      )}
    </div>
  );

  const contactList = contacts.length ? (
    <div
      style={{
        display: "flex",
        flexDirection: wide ? "row" : "column",
        flexWrap: wide ? "wrap" : "nowrap",
        justifyContent: "center",
        alignItems: row ? "flex-start" : "center",
        gap: 0.4 * gap,
        maxWidth: textW,
      }}
    >
      {contacts.map((c, i) => {
        const sp = at(0.24 + i * 0.06, true);
        const bg = i === 0 ? COLORS.teal : COLORS.ink; // accent only on the first (phone) pill
        const fs = fit(c, pillBase, pillAvail, 0.58, 1.8);
        return (
          <div
            key={i}
            style={{
              backgroundColor: bg,
              color: textForBg(bg),
              borderRadius: 999,
              padding: `${0.32 * fs}px ${0.9 * fs}px`,
              fontFamily: FONTS.display,
              fontWeight: FONTS.displayWeight,
              fontStyle: "italic",
              fontSize: fs,
              lineHeight: 1.1,
              maxWidth: "100%",
              overflowWrap: "anywhere",
              textAlign: "center",
              opacity: Math.min(1, sp * 2),
              transform: `translateY(${(1 - sp) * 50 * s}px) scale(${0.7 + 0.3 * Math.min(1, sp)})`,
            }}
          >
            {c}
          </div>
        );
      })}
    </div>
  ) : null;

  const nameEl = name ? <div style={nameStyle}>{name}</div> : null;

  return (
    <AbsoluteFill style={{ fontFamily: FONTS.body, alignItems: "center", justifyContent: "center", opacity: out }}>
      {row ? (
        <div style={{ display: "flex", flexDirection: "row", alignItems: "center", gap }}>
          {photo}
          <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-start", gap: 0.6 * gap, width: textW }}>
            {nameEl}
            {contactList}
          </div>
        </div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap }}>
          {nameEl}
          {photo}
          {contactList}
        </div>
      )}
    </AbsoluteFill>
  );
};

export default AgenteRevelacao;

